from collections import deque

def rolling_totals(values, width):
    if width <= 0:
        raise ValueError("width must be positive")
    recent = deque()
    total = 0
    for value in values:
        if len(recent) == width:
            total = total - recent.popleft()
        recent.append(value)
        total = total + value
        yield total

for total in rolling_totals(iter((2, 1, 4, 3)), 3):
    print(total)
